from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

W, G, S = 4, 6, 4
N = G * S  # 24

vpool = IDPool()
def x(p, w, g):
    return vpool.id(('x', p, w, g))
def m(p, q, w):  # meet indicator: p<q same group in week w
    return vpool.id(('m', p, q, w))

clauses = []

# Each player in exactly one group per week
for p in range(N):
    for w in range(W):
        lits = [x(p, w, g) for g in range(G)]
        cnf = CardEnc.equals(lits=lits, bound=1, vpool=vpool, encoding=EncType.pairwise)
        clauses.extend(cnf.clauses)

# Each group has exactly S players per week
for w in range(W):
    for g in range(G):
        lits = [x(p, w, g) for p in range(N)]
        cnf = CardEnc.equals(lits=lits, bound=S, vpool=vpool, encoding=EncType.seqcounter)
        clauses.extend(cnf.clauses)

# meeting: m(p,q,w) <=> exists g: x(p,w,g) & x(q,w,g)
# We define: m(p,q,w) implied by x(p,w,g) & x(q,w,g), and at most one meeting across weeks
for p in range(N):
    for q in range(p+1, N):
        for w in range(W):
            for g in range(G):
                # x(p,w,g) & x(q,w,g) -> m(p,q,w)
                clauses.append([-x(p,w,g), -x(q,w,g), m(p,q,w)])
        # at most one week they meet
        cnf = CardEnc.atmost(lits=[m(p,q,w) for w in range(W)], bound=1, vpool=vpool, encoding=EncType.pairwise)
        clauses.extend(cnf.clauses)

# Symmetry: week 1 fix - first week groups 0..5 contiguous
for p in range(N):
    w = 0
    g = p // S
    clauses.append([x(p, w, g)])

# Player 0 in group 0 every week
for w in range(W):
    clauses.append([x(0, w, 0)])

solver = Glucose4()
for c in clauses:
    solver.add_clause(c)

print("solving...")
res = solver.solve()
print(res)
if res:
    model = set(solver.get_model())
    out = [0]*(W*N)
    for p in range(N):
        for w in range(W):
            for g in range(G):
                if x(p,w,g) in model:
                    out[w*N + p] = g
    print(out)
    # verify
    for w in range(W):
        groups = {}
        for p in range(N):
            groups.setdefault(out[w*N+p], []).append(p)
        print(w, groups)
    pairs = {}
    for w in range(W):
        for p in range(N):
            for q in range(p+1,N):
                if out[w*N+p] == out[w*N+q]:
                    pairs[(p,q)] = pairs.get((p,q),0)+1
    print("max pair meet:", max(pairs.values()))
